import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import {
  tableCellBaseClass,
  tableCellLeftBorderClass,
  tableCellRightBorderClass,
  tableRowClass
} from "@/components/ui/tableStyles";
import { cn } from "@/lib/utils";

type InventoryItem = {
  id: string;
  name: string;
  rarity: string;
  price: string | number;
  location: string;
};

type InventoryRowProps = {
  item: InventoryItem;
  selected: boolean;
  onToggle: (id: string) => void;
};

function getRarityClass(rarity: string) {
  if (rarity === "Covert") {
    return "text-[var(--danger)]";
  }

  if (rarity === "Classified") {
    return "text-[var(--accent)]";
  }

  return "text-[var(--text-muted)]";
}

export default function InventoryRow({
  item,
  selected,
  onToggle
}: InventoryRowProps) {
  return (
    <TableRow className={tableRowClass}>
      <TableCell
        className={cn(
          tableCellBaseClass,
          tableCellLeftBorderClass,
          "w-[32px] rounded-l-xl pl-4"
        )}
      >
        <Checkbox
          checked={selected}
          className="border-[var(--border)] data-[state=checked]:bg-[var(--accent)] data-[state=checked]:text-black"
          onCheckedChange={() => onToggle(item.id)}
        />
      </TableCell>
      <TableCell className={cn(tableCellBaseClass, "w-[40px] px-2")}>
        <div className="h-9 w-9 rounded-md border border-[var(--border)] bg-[var(--panel-soft)]" />
      </TableCell>
      <TableCell className={cn(tableCellBaseClass, "px-3 truncate")}>
        {item.name}
      </TableCell>
      <TableCell
        className={cn(tableCellBaseClass, "px-3", getRarityClass(item.rarity))}
      >
        {item.rarity}
      </TableCell>
      <TableCell className={cn(tableCellBaseClass, "px-3")}>
        {item.price}
      </TableCell>
      <TableCell
        className={cn(
          tableCellBaseClass,
          tableCellRightBorderClass,
          "rounded-r-xl px-4 text-[#A1ADD6]"
        )}
      >
        {item.location}
      </TableCell>
    </TableRow>
  );
}
